const t={ASSETS:["Current Assets","Bank Accounts","Cash-in-Hand","Deposits (Asset)","Loans & Advances (Asset)","Stock-in-Hand","Sundry Debtors","Fixed Assets","Investments","Misc. Expenses (ASSET)"],LIABILITIES:["Branch / Divisions","Capital Account","Reserves & Surplus","Current Liabilities","Duties & Taxes","Provisions","Sundry Creditors","Loans (Liability)","Bank OD A/c","Secured Loans","Unsecured Loans","Suspense A/c","Profit & Loss A/c"],EXPENSES:["Direct Expenses","Indirect Expenses","Purchase Accounts"],INCOME:["Direct Incomes","Indirect Incomes","Sales Accounts"]},r=s=>{for(const[e,n]of Object.entries(t))if(n.includes(s))return e;return"ASSETS"};export{t as S,r as g};
